source('/home/jinshengxi/bladder_metabolism/results/llps_C5_cellchat_visualization_v3/scripts/common.R');STAGE<-'06_nichenet_figures.R';startstage()
a<-r('tables/NicheNet_activities.csv')[!startsWith(program,'LOPO_')];np<-fread(file.path(N2,'00_input_audit/official_human_v2_LR_pairs.tsv'));es<-r('tables/expression_summary.csv');d1<-fread(file.path(N1,'02_receiver_geneset/frozen_program_genes.tsv'))[in_background==TRUE,.(program,gene)];d1[,source:='standard'];d2<-fread(file.path(N2,'02_nominal_response_genesets/frozen_genesets.tsv'));d2[,source:='nominal'];defs<-rbind(d1,d2,fill=TRUE);w(defs,'tables/NicheNet_frozen_definitions.csv')
