ltpath<-file.path(BASE,'cellchat_nichechat_fibro7/05_nichenet_preflight/ligand_target_matrix_nsga2r_final.rds');lt<-readRDS(ltpath);audit<-list()
nnexp<-function(genes,group,nm){selected_group<-group;z<-es[group==selected_group & gene%in%genes];z[,gene:=factor(gene,levels=rev(genes))];p<-ggplot(z,aes(group,gene,color=patient_mean,size=patient_fraction))+geom_point()+scale_size_area(max_size=6,limits=c(0,1),labels=scales::label_percent(),name='Mean patient detection')+scale_color_viridis_c(guide=cb(),name='Mean patient expression')+jin_theme()+labs(x=NULL,y=NULL);expfig(p,'07_NicheNet',nm,z,7,max(5,length(genes)*.24+2),role='Supplementary figures',source='Existing NicheNet candidate sets + v2 RNA cache expression',threshold='Tumor expression >=1 cell',unit='patient-condition balanced',purpose='Expression evidence separate from ligand activity',limitation='No NicheNet rerun; expression alone does not establish activity')}
for(i in seq_len(nrow(unique(a[,.(source,program)])))){
 key<-unique(a[,.(source,program)])[i];src<-key$source;pg<-key$program;act<-a[source==src&program==pg][order(rank)];prefix<-paste(src,clean(pg),sep='_');gs<-defs[source==src&program==pg,gene];ligs<-unique(c(head(act$test_ligand,20),intersect(FOCUS,act$test_ligand)));full<-CJ(ligand=act$test_ligand,target=gs);full[,weight:=NA_real_];ix<-which(full$ligand%in%colnames(lt)&full$target%in%rownames(lt));full$weight[ix]<-lt[cbind(match(full$target[ix],rownames(lt)),match(full$ligand[ix],colnames(lt)))];full[,`:=`(program=pg,source=src)];w(full,paste0('tables/NicheNet_',prefix,'_complete_prior_targets.csv.gz'));audit[[i]]<-data.table(source=src,program=pg,ligands=nrow(act),targets=length(gs),missing_prior=sum(is.na(full$weight)))
 activity<-function(d,suffix){p<-ggplot(d,aes(aupr_corrected,reorder(test_ligand,-rank)))+geom_col(fill='#637BA8',width=.75)+jin_theme()+labs(x='Existing ligand activity (corrected AUPR)',y=NULL);expfig(p,'07_NicheNet',paste0(prefix,'_activity_',suffix),d,9,max(5,nrow(d)*.22+1.5),role=if(pg=='Set_B'&suffix=='top20')'Main figure candidates'else'Supplementary figures',source=paste(src,'existing NicheNet activities'),threshold='Historical frozen response definition',unit='ligand prior ranking',purpose=paste(pg,'activity; ranks unchanged'),limitation='Standard programs are priors; nominal response genes are not FDR-significant DEG; ranking is not independent functional validation')}
 activity(head(act,20),'top20');if(pg=='Set_B'){for(j in seq_len(ceiling(nrow(act)/40)))activity(act[seq.int((j-1)*40+1,min(j*40,nrow(act)))],paste0('all_page',j))}
 nnexp(head(act$test_ligand,20),C5,paste0(prefix,'_ligand_expression'))
 receptors<-unique(np[ligand%in%ligs,receptor]);recstats<-es[group=='Endothelial'&gene%in%receptors][order(-patient_fraction,-patient_mean)];recs<-head(recstats$gene,30);nnexp(recs,'Endothelial',paste0(prefix,'_receptor_expression'))
 links<-CJ(ligand=ligs,receptor=receptors);links[,prior_link:=as.numeric(paste(ligand,receptor)%in%paste(np$ligand,np$receptor))];w(links,paste0('tables/NicheNet_',prefix,'_full_LR_prior.csv'));show<-links[receptor%in%recs];p<-heat(show,'receptor','ligand','prior_link',recs,ligs,c(0,1),fillname='Existing LR prior (0/1)');expfig(p,'07_NicheNet',paste0(prefix,'_LR_prior'),show,13,max(6,length(ligs)*.23+2),role='Supplementary figures',source='Existing official human v2 NicheNet LR prior',threshold='Not CellChat filtered',unit='database ligand-receptor edge',purpose='Known prior edges, not inferred communication',limitation='0 means absent from this prior, not absent biological interaction; selected receptor columns by measured Endothelial detection; all links in tables')
 targ<-full[ligand%in%ligs];tr<-targ[,.(max_weight=max(weight,na.rm=TRUE)),by=target][order(-max_weight,target)];tg<-head(tr$target,35);z<-targ[target%in%tg];p<-heat(z,'target','ligand','weight',tg,ligs,fillname='Prior regulatory potential');expfig(p,'07_NicheNet',paste0(prefix,'_LT_compact'),z,14,max(6,length(ligs)*.23+2),role=if(pg=='Set_B')'Main figure candidates'else'Supplementary figures',source='Existing ligand-target prior, subset of frozen response genes',threshold='Historical program',unit='prior weight',purpose='Top35 targets by maximum prior weight among displayed ligands',limitation='Prior potential is not measured target response or causal validation; all246 ligands x frozen targets in complete CSV')
 if(pg=='Set_B'){for(j in seq_len(ceiling(length(gs)/35))){tg<-sort(gs)[seq.int((j-1)*35+1,min(j*35,length(gs)))];z<-targ[target%in%tg];p<-heat(z,'target','ligand','weight',tg,ligs,c(0,max(targ$weight,na.rm=TRUE)),fillname='Prior regulatory potential');expfig(p,'07_NicheNet',paste0(prefix,'_LT_all_targets_page',j),z,14,max(6,length(ligs)*.23+2),role='Supplementary figures',source='Existing ligand-target prior',threshold='Frozen nominal Set B',unit='prior weight',purpose='All frozen Set B targets; top20 plus available focused ligands',limitation='All246 ligand matrix in CSV; plots use declared ligand shortlist, no activity re-estimation')}}
}
